// Fake `aws` (AWS CLI v2) for Windows CI, started through aws.cmd, an npm shim (the real aws is aws.exe).
//
// `aws configure export-credentials --format process` prints made-up credentials as JSON with CR LF line ends, or,
// with FAKE_AWS_NO_CREDENTIALS set, fails the way the real CLI does without credentials.
// `aws bedrock-runtime converse --cli-input-json file://... --region r --output json ...` reads the request file the
// way the real CLI does (drop `file://`, open the rest), insists on the Windows form file://C:/... on Windows, and
// answers in Converse's JSON shape: a write_file tool call for "hello.txt" when the task asks to write and no tool
// result has come back yet, otherwise text. A model id containing "bad-model" gives a ValidationException; a task
// containing "sleep" leaves a sleeping process tree.
'use strict';
const fs = require('fs');
const { EOL, record, option, sleepTree } = require('fake-common');

const argv = process.argv.slice(2);
record('aws', argv);
const json = (object) => process.stdout.write(JSON.stringify(object, null, 4).replace(/\n/g, EOL) + EOL);
const fail = (code, message) => { process.stderr.write(EOL + message + EOL); process.exit(code); };

if (argv[0] === 'configure' && argv[1] === 'export-credentials') {
  if (option(argv, '--format') !== 'process') fail(252, 'fake aws: expected --format process');
  if (process.env.FAKE_AWS_NO_CREDENTIALS) fail(253, 'Unable to locate credentials. You can configure credentials by running "aws configure".');
  json({
    Version: 1,
    AccessKeyId: 'AKIAFAKEFAKEFAKEFAKE',
    SecretAccessKey: 'fake/secret/key',
    SessionToken: 'fake-session-token',
    Expiration: new Date(Date.now() + 3600 * 1000).toISOString().replace(/\.\d+Z$/, '+00:00'),
  });
  process.exit(0);
}

if (argv[0] === 'bedrock-runtime' && argv[1] === 'converse') {
  const input = option(argv, '--cli-input-json') || '';
  const windowsForm = /^file:\/\/[A-Za-z]:\//;
  if (!input.startsWith('file://') || (process.platform === 'win32' && !windowsForm.test(input))) {
    fail(252, `fake aws: --cli-input-json must be file://C:/... on Windows, got ${input}`);
  }
  if (!option(argv, '--region') || option(argv, '--output') !== 'json') fail(252, 'fake aws: expected --region and --output json');
  let request;
  try {
    request = JSON.parse(fs.readFileSync(input.slice('file://'.length), 'utf8'));
  } catch (error) {
    fail(255, `Error parsing parameter '--cli-input-json': Unable to load paramfile ${input}: ${error.message}`);
  }
  if (String(request.modelId).includes('bad-model')) {
    fail(254, 'An error occurred (ValidationException) when calling the Converse operation: The provided model identifier is invalid.');
  }
  const messages = request.messages || [];
  const firstText = ((messages[0] || {}).content || []).map((block) => block.text || '').join(' ');
  if (/\bsleep\b/.test(firstText)) { sleepTree(); return; }
  const last = messages[messages.length - 1] || { content: [] };
  const gotResult = (last.content || []).some((block) => block.toolResult);
  const wantsWrite = /\bwrite\b/.test(firstText) && !gotResult;
  const content = wantsWrite
    ? [{ text: 'Writing hello.txt.' }, { toolUse: { toolUseId: 'tooluse_fake1', name: 'write_file', input: { path: 'hello.txt', content: 'hi from bedrock' } } }]
    : [{ text: gotResult ? 'Bedrock fake: finished after the tool ran.' : 'Hello from fake Bedrock.' }];
  json({
    output: { message: { role: 'assistant', content } },
    stopReason: wantsWrite ? 'tool_use' : 'end_turn',
    usage: { inputTokens: 10, outputTokens: 5, totalTokens: 15 },
    metrics: { latencyMs: 12 },
  });
  process.exit(0);
}

fail(252, `fake aws: unsupported command: ${argv.join(' ')}`);
